var WD_NAMES=['星期日','星期一','星期二','星期三','星期四','星期五','星期六'];
function dateInfo(dateStr){
  var d = dateStr ? new Date(dateStr) : new Date();
  if(isNaN(d.getTime())) return {ok:false, reason:'invalid date'};
  var start=new Date(d.getFullYear(),0,1);
  var doy=Math.floor((d-start)/86400000)+1;
  var t=new Date(d.getFullYear(), d.getMonth(), d.getDate());
  t.setDate(t.getDate()+3-((t.getDay()+6)%7));
  var w1=new Date(t.getFullYear(),0,4);
  var week=1+Math.round(((t-w1)/86400000-3+((w1.getDay()+6)%7))/7);
  var y=d.getFullYear();
  var leap=(y%4===0 && y%100!==0) || y%400===0;
  return {ok:true, weekday:WD_NAMES[d.getDay()], dayOfYear:doy, isoWeek:week, leap:leap, year:y};
}

var EXPORTS={dateInfo:dateInfo};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.WeekdayForgePure = EXPORTS; }
